-- Loads the simulated dataset. Run from the dataset root:  psql -d keepwell -v ON_ERROR_STOP=1 -f load.sql
-- Schema (keepwell_schema.sql) must already be applied. Append-only triggers are not affected: appliance_event rows are inserted, never updated.
BEGIN;
SET search_path = kw, public;
SET kw.role = 'platform';
\copy brand (id, name, forwarding_enabled, created_at) FROM 'csv/brand.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy appliance_category (code, name) FROM 'csv/appliance_category.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy category_norm (id, category_code, service_interval_months, typical_life_years, valid_from, valid_to) FROM 'csv/category_norm.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy appliance_model (id, brand_id, category_code, model_code, series, year_from, specs, created_at) FROM 'csv/appliance_model.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy rate_card (id, category_code, job_type, complexity_band, visit_fee_paise, labour_paise, valid_from, valid_to) FROM 'csv/rate_card.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy kb_document (id, title, brand_id, category_code, model_series, doc_type, language, version_year, valid_to, authority, audience, storage_uri, file_search_store, file_search_doc, rights_status, created_at, updated_at) FROM 'csv/kb_document.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy coverage_plan (id, kind, provider_name, brand_id, terms_doc_id, covers, created_at) FROM 'csv/coverage_plan.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy safe_fix_catalogue (id, code, category_code, brand_id, model_series, fault_family, title, symptom_terms, steps, step_count, est_minutes, reversible, needs_tools, opens_panel, manual_doc_id, manual_page, worst_case, reviewer_name, reviewer_role, reviewed_on, review_due, status, created_at) FROM 'csv/safe_fix_catalogue.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy urgency_rule (id, code, class, category_code, description, condition, protective_message, source, active, created_at) FROM 'csv/urgency_rule.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy service_centre (id, name, address_line, pincode, location, service_pincodes, categories, hours, default_language, onboarding_status, created_at, updated_at) FROM 'csv/service_centre.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy centre_commercial (centre_id, commission_terms, payout_ref) FROM 'csv/centre_commercial.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy centre_channel (id, centre_id, channel, number_ref, provider_ref, status) FROM 'csv/centre_channel.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy centre_brand_authorisation (id, centre_id, brand_id, level, valid_from, valid_to, evidence_ref) FROM 'csv/centre_brand_authorisation.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy centre_capacity (id, centre_id, category_code, job_type, daily_slots, urgent_holdback) FROM 'csv/centre_capacity.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy centre_price (id, centre_id, category_code, job_type, complexity_band, visit_fee_paise, labour_paise, valid_from, valid_to) FROM 'csv/centre_price.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy retailer (id, name, city, created_at) FROM 'csv/retailer.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy technician (id, centre_id, name, phone_enc, phone_hash, languages, shift_start, shift_end, route_anchor_type, route_anchor, vehicle_type, tool_kit, identity_verified, safety_certs, active, created_at, updated_at) FROM 'csv/technician.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy technician_skill (id, technician_id, centre_id, brand_id, category_code, fault_class, level, certified_on, certificate_ref) FROM 'csv/technician_skill.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy technician_metrics (technician_id, category_code, period_end, jobs, first_time_fix_rate, on_time_rate, repeat_visit_rate_30d, acceptance_rate, avg_quote_variance_pct, computed_at, centre_id) FROM 'csv/technician_metrics.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy parts_centre (id, name, address_line, pincode, location, hours, pickup_supported, delivery_supported, fill_rate, stock_accuracy, active, created_at, updated_at) FROM 'csv/parts_centre.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy parts_centre_brand (parts_centre_id, brand_id, is_authorised) FROM 'csv/parts_centre_brand.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy part_catalogue (id, brand_id, part_no, name, kind, substitution_group, mrp_paise, warranty_months) FROM 'csv/part_catalogue.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy part_compatibility (part_id, model_id, revision) FROM 'csv/part_compatibility.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy stock (id, holder_type, holder_id, centre_id, part_id, quantity, as_of, source, confidence) FROM 'csv/stock.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy community (id, name, pincode, location, contact_ref, created_at) FROM 'csv/community.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy household (id, phone_enc, phone_hash, phone_verified_at, verified_via, language, address_line, pincode, location, location_verified, community_id, access_notes, preferred_slots, status, merged_into_id, created_at, updated_at) FROM 'csv/household.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy household_member (id, household_id, name, phone_enc, phone_hash, role, may_raise_ticket, created_at) FROM 'csv/household_member.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy household_centre_link (household_id, centre_id, first_contact_at, last_served_at, contact_count) FROM 'csv/household_centre_link.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy appliance (id, household_id, category_code, brand_id, model_id, model_text, serial_no, purchase_date, purchase_source, invoice_file_ref, install_date, installed_by, warranty_start, warranty_end, coverage_plan_id, usage_profile, room, care_index, care_index_reasons, care_index_updated_at, last_service_at, last_served_centre_id, next_due_at, serial_norm, identity_status, merged_into_id, first_seen_via, first_seen_centre_id, status, created_at, updated_at) FROM 'csv/appliance.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy external_ref (id, entity_type, entity_id, ref_type, ref_norm, owner_type, owner_id, verified, first_seen_at) FROM 'csv/external_ref.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy scoring_config (id, kind, name, weights, params, valid_from, created_by) FROM 'csv/scoring_config.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy brand_referral (id, centre_id, brand_id, brand_request_ref, received_at, payload, claimed_entitlement, authority_checked, household_contacted_at, status) FROM 'csv/brand_referral.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy retailer_handover (id, centre_id, retailer_id, order_ref, invoice_no, purchase_date, requested_job, payload, received_at, status) FROM 'csv/retailer_handover.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy ticket (id, centre_id, household_id, appliance_id, job_type, raw_inputs, case_card, safety_flag, safety_reason, entitlement, coverage_plan_id, visit_address, visit_location, status, first_visit_by, created_at, updated_at, closed_at, trigger, channel, brand_referral_id, retailer_handover_id, origin_reminder_id, urgency_class, needed_by, resolution, closure_otp_ref, closure_confirmed_at) FROM 'csv/ticket.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy conversation (id, centre_id, ticket_id, household_id, channel, modality, parent_conversation_id, language, started_at, ended_at, end_reason, recording_consent, transcript_uri, summary) FROM 'csv/conversation.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy urgency_assessment (id, centre_id, ticket_id, class, rule_codes, facts, assessed_by, reason, protective_steps_sent, created_at) FROM 'csv/urgency_assessment.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy consent_gate (id, centre_id, ticket_id, conversation_id, gate, asked_at, answer, answered_at, choice, not_asked_reason) FROM 'csv/consent_gate.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy clarifying_qa (id, centre_id, ticket_id, conversation_id, seq, question, answer, answer_source, asked_at) FROM 'csv/clarifying_qa.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy diagnosis_session (id, centre_id, ticket_id, conversation_id, provider, model, link_route, started_at, ended_at, duration_s, video_on, compression_on, resumptions, frames_consent, end_reason, observations) FROM 'csv/diagnosis_session.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy diagnosis_media (id, centre_id, session_id, kind, storage_uri, retain_until, created_at) FROM 'csv/diagnosis_media.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy fix_attempt (id, centre_id, ticket_id, catalogue_id, conversation_id, session_id, offered_at, started_at, ended_at, steps_done, outcome, household_report, observed_on_video) FROM 'csv/fix_attempt.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy appliance_event (id, appliance_id, event_type, occurred_at, ticket_id, details, centre_id, visibility) FROM 'csv/appliance_event.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy quote (id, ticket_id, version, quote_type, valid_until, approved_at, approval_channel, approval_ref, created_at, centre_id) FROM 'csv/quote.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy quote_line (id, quote_id, line_type, description, part_id, quantity, amount_paise, payer, plan_id, centre_id) FROM 'csv/quote_line.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy visit (id, ticket_id, technician_id, centre_id, planned_start, planned_end, is_return_visit, parent_visit_id, check_in_at, check_in_location, check_out_at, checklist, outcome, outcome_notes, root_cause_confirmed, closure_otp_ref, closure_confirmed_at, rating, created_at, updated_at) FROM 'csv/visit.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy technician_availability (id, technician_id, centre_id, slot_start, slot_end, status, held_until, visit_id) FROM 'csv/technician_availability.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy visit_part_used (id, visit_id, part_id, serial_no, quantity, source_type, centre_id) FROM 'csv/visit_part_used.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy reservation (id, centre_id, part_id, quantity, holder_type, holder_id, visit_id, ready_by, status, created_at) FROM 'csv/reservation.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy route (id, technician_id, route_date, batched, optimiser, planned_travel_min, actual_travel_min, created_at, centre_id) FROM 'csv/route.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy route_stop (route_id, seq, visit_id, planned_arrival, actual_arrival, centre_id) FROM 'csv/route_stop.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy settlement_line (id, ticket_id, party_type, party_id, direction, amount_paise, status, payment_ref, due_at, settled_at, centre_id) FROM 'csv/settlement_line.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy feedback (id, ticket_id, visit_id, from_type, rating, reason_codes, comment, is_dispute, resolution, created_at, centre_id) FROM 'csv/feedback.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy reminder (id, household_id, appliance_id, reminder_type, due_on, template_name, whatsapp_category, status, scheduled_at, sent_at, delivered_at, read_at, action_taken, ticket_id, created_at, centre_id) FROM 'csv/reminder.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy experience_case (id, source_visit_id, brand_id, category_code, model_series, pincode, symptom_text, error_code, root_cause, parts, duration_min, cost_paise, outcome, verified_by_technician, embedding, created_at, self_fix_tried) FROM 'csv/experience_case.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
\copy consent_ledger (id, subject_type, subject_id, purpose, scope_centre_id, notice_version, granted_at, channel, withdrawn_at, evidence) FROM 'csv/consent_ledger.csv' WITH (FORMAT csv, HEADER true, NULL '\N')
COMMIT;
ANALYZE;
